dding:11px;border:1px solid #d8ded8;font:inherit}.form button{background:#10211f;color:#fff;font-weight:bold}.notice{background:#e6f8c7;padding:10px}.error{background:#ffe2de;padding:10px}.muted{color:#64716d;line-height:1.5}.back{color:#10211f}</style></head><body><main class="wrap"><a class="back" href="/nexustraveltech/admin/">← Panele dön</a><div class="card"><h1>Gemini görsel AI</h1><p class="muted">Fotoğraf benzerliği ve ürün tekrarı analizi. Anahtar şifreli tutulur, tekrar görüntülenmez. Durum: <b><?= $has?'aktif':'anahtar bekliyor' ?></b></p><?php if($message):?><p class="notice"><?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post" class="form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['admin_csrf'])?>"><label>Gemini API anahtarı<input type="password" name="api_key" autocomplete="new-password" placeholder="<?= $has?'Değiştirmek için yeni anahtarı girin':'AIza...'?>"></label><label>Model<input name="model" value="<?=htmlspecialchars((string)($current['model']??'gemini-3.6-flash'))?>"></label><button>Gemini ayarlarını kaydet</button></form></div></main></body></html>
